package com.fasterxml.jackson.databind.deser.std;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.databind.BeanProperty;
import com.fasterxml.jackson.databind.DeserializationContext;
import com.fasterxml.jackson.databind.DeserializationFeature;
import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.JsonDeserializer;
import com.fasterxml.jackson.databind.JsonMappingException;
import com.fasterxml.jackson.databind.annotation.JacksonStdImpl;
import com.fasterxml.jackson.databind.deser.ContextualDeserializer;
import com.fasterxml.jackson.databind.deser.ResolvableDeserializer;
import com.fasterxml.jackson.databind.jsontype.TypeDeserializer;
import com.fasterxml.jackson.databind.type.TypeFactory;
import com.fasterxml.jackson.databind.util.ClassUtil;
import com.fasterxml.jackson.databind.util.ObjectBuffer;
import java.io.*;
import java.io.IOException;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.junit.MockitoJUnitRunner;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertSame;
import static org.mockito.Mockito.verifyNoInteractions;

@RunWith(MockitoJUnitRunner.class)
public class UntypedObjectDeserializer_createContextual_TriageGen0Test {

    @Mock
    private DeserializationContext ctxt;

    @Mock
    private BeanProperty property;

    /**
     * Test Case 1: Tests the "Vanilla" branch.
     * Conditions:
     * _stringDeserializer == null
     * _numberDeserializer == null
     * _mapDeserializer == null
     * _listDeserializer == null
     * getClass() == UntypedObjectDeserializer.class
     */
    @Test
    public void testCreateContextual_ReturnsVanilla() throws Exception {
        // Using default constructor ensures all internal deserializers are null
        UntypedObjectDeserializer deserializer = new UntypedObjectDeserializer();

        // The internal 'Vanilla.std' is the expected return value when conditions are met
        // Since Vanilla is a private static inner class or field, we check if return is not 'this'
        // and matches the logic of returning a standard instance.
        JsonDeserializer<?> result = deserializer.createContextual(ctxt, property);

        // In Jackson source, Vanilla.std is a singleton instance used for untyped objects
        // We verify it's not the instance itself (which would imply the second return path)
        // and it's not null.
        org.junit.Assert.assertNotSame(deserializer, result);
        org.junit.Assert.assertNotNull(result);
    }

    /**
     * Test Case 2: Tests the "return this" branch (String deserializer is NOT null).
     */
    @Test
    public void testCreateContextual_ReturnsThis_WhenStringDeserializerIsPresent() throws Exception {
        // We need to trigger the condition where one of the deserializers is not null.
        // Since the fields are protected/private and there's no setter, we use the 
        // constructor that might initialize them, or we simulate via a subclass if possible.
        // However, the constructor UntypedObjectDeserializer(JavaType listType, JavaType mapType) 
        // is available.

        // To strictly follow the logic: if we can't set fields via constructor, 
        // we rely on the fact that if any field is non-null, it returns 'this'.
        // Note: In the actual Jackson source, the constructor (JavaType, JavaType) 
        // initializes _listDeserializer and _mapDeserializer.

        // We use a dummy JavaType if possible, but since we can't easily mock JavaType 
        // without a lot of boilerplate, we assume the constructor sets them.
        // If the constructor doesn't set them, we'd need reflection.

        // Let's use Reflection to ensure we hit the branch coverage for "return this"
        UntypedObjectDeserializer deserializer = new UntypedObjectDeserializer();
        java.lang.reflect.Field stringField = UntypedObjectDeserializer.class.getDeclaredField("_stringDeserializer");
        stringField.setAccessible(true);
        stringField.set(deserializer, com.fasterxml.jackson.databind.deser.std.StringDeserializer.instance);

        JsonDeserializer<?> result = deserializer.createContextual(ctxt, property);

        assertSame("Should return 'this' when _stringDeserializer is not null", deserializer, result);
    }

    /**
     * Test Case 3: Tests the "return this" branch (Number deserializer is NOT null).
     */
    @Test
    public void testCreateContextual_ReturnsThis_WhenNumberDeserializerIsPresent() throws Exception {
        UntypedObjectDeserializer deserializer = new UntypedObjectDeserializer();
        java.lang.reflect.Field numberField = UntypedObjectDeserializer.class.getDeclaredField("_numberDeserializer");
        numberField.setAccessible(true);
        numberField.set(deserializer, com.fasterxml.jackson.databind.deser.std.NumberDeserializer.instance);

        JsonDeserializer<?> result = deserializer.createContextual(ctxt, property);

        assertSame("Should return 'this' when _numberDeserializer is not null", deserializer, result);
    }

    /**
     * Test Case 4: Tests the "return this" branch (Map deserializer is NOT null).
     */
    @Test
    public void testCreateContextual_ReturnsThis_WhenMapDeserializerIsPresent() throws Exception {
        UntypedObjectDeserializer deserializer = new UntypedObjectDeserializer();
        java.lang.reflect.Field mapField = UntypedObjectDeserializer.class.getDeclaredField("_mapDeserializer");
        mapField.setAccessible(true);
        mapField.set(deserializer, com.fasterxml.jackson.databind.deser.std.MapDeserializer.instance);

        JsonDeserializer<?> result = deserializer.createContextual(ctxt, property);

        assertSame("Should return 'this' when _mapDeserializer is not null", deserializer, result);
    }

    /**
     * Test Case 5: Tests the "return this" branch (List deserializer is NOT null).
     */
    @Test
    public void testCreateContextual_ReturnsThis_WhenListDeserializerIsPresent() throws Exception {
        UntypedObjectDeserializer deserializer = new UntypedObjectDeserializer();
        java.lang.reflect.Field listField = UntypedObjectDeserializer.class.getDeclaredField("_listDeserializer");
        listField.setAccessible(true);
        listField.set(deserializer, com.fasterxml.jackson.databind.deser.std.ListDeserializer.instance);

        JsonDeserializer<?> result = deserializer.createContextual(ctxt, property);

        assertSame("Should return 'this' when _listDeserializer is not null", deserializer, result);
    }

    /**
     * Test Case 6: Tests the "return this" branch via Subclass (getClass() != UntypedObjectDeserializer.class).
     */
    @Test
    public void testCreateContextual_ReturnsThis_WhenSubclassed() throws Exception {
        UntypedObjectDeserializer subClassDeserializer = new UntypedObjectDeserializer() {};

        // Even if all deserializers are null, because it is a subclass, 
        // it should return 'this' instead of Vanilla.std
        JsonDeserializer<?> result = subClassDeserializer.createContextual(ctxt, property);

        assertSame("Should return 'this' when it is a subclass", subClassDeserializer, result);
    }
}
